import{_ as o,o as t,c as n,a8 as a}from"./chunks/framework.On_KnKH5.js";const p=JSON.parse('{"title":"Tagging and versioning conventions","description":"","frontmatter":{},"headers":[],"relativePath":"versioning.md","filePath":"versioning.md"}'),i={name:"versioning.md"};function s(r,e,c,d,l,g){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="tagging-and-versioning-conventions" tabindex="-1">Tagging and versioning conventions <a class="header-anchor" href="#tagging-and-versioning-conventions" aria-label="Permalink to “Tagging and versioning conventions”">​</a></h1><h2 id="tag-format" tabindex="-1">Tag format <a class="header-anchor" href="#tag-format" aria-label="Permalink to “Tag format”">​</a></h2><p><code>tag.yml</code> creates the tag. It encodes both the <strong>Nx project name</strong> and <strong>semver</strong>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;nx-project-name&gt;/v&lt;semver&gt;</span></span></code></pre></div><p><strong>Rules:</strong></p><ul><li><code>&lt;nx-project-name&gt;</code> must be the <strong>exact</strong> Nx project name (<code>npx nx show projects</code>). Example: <code>bcew-blocks</code>. If you rename the project, later tags use the <strong>new</strong> name; do not retag history. See <a href="./renaming-projects">Renaming a plugin or theme</a>.</li><li><code>&lt;semver&gt;</code> is prefixed with <code>v</code> in the tag. The workflow only creates <code>X.Y.Z</code> or <code>X.Y.Z-alpha.N</code> (examples: <code>v1.0.0</code>, <code>v1.1.0-alpha.1</code>). Older shapes such as <code>v1.1.0-a1</code> are ignored when the next version is chosen.</li><li>Invalid examples: <ul><li>Wrong project slug not in Nx graph</li><li>Non-semver suffixes such as <code>v100-testing-tag</code> for production consumption</li></ul></li></ul><p>The workflow strips the leading <code>v</code> for the version recorded in <code>packages.json</code> while keeping the full tag for GitHub Release URLs.</p><h2 id="branch-naming" tabindex="-1">Branch naming <a class="header-anchor" href="#branch-naming" aria-label="Permalink to “Branch naming”">​</a></h2><p>Use descriptive, lowercase, hyphenated branches:</p><table tabindex="0"><thead><tr><th>Prefix</th><th>Use</th></tr></thead><tbody><tr><td><code>feature/</code></td><td>New functionality</td></tr><tr><td><code>fix/</code> or <code>bugfix/</code></td><td>Defect fixes</td></tr><tr><td><code>chore/</code></td><td>Tooling, housekeeping</td></tr><tr><td><code>docs/</code></td><td>Documentation only</td></tr></tbody></table><p>Examples: <code>feature/add-hero-block</code>, <code>fix/wp-env-port-conflict</code>.</p><p><strong>Default branch:</strong> <code>main</code> — PRs usually target <code>main</code>; <code>nx.json</code> sets <code>defaultBase</code> to <code>origin/main</code> for local <code>nx affected</code> comparisons.</p><h2 id="wordpress-version-on-release" tabindex="-1">WordPress version on release <a class="header-anchor" href="#wordpress-version-on-release" aria-label="Permalink to “WordPress version on release”">​</a></h2><p>When <strong><code>tag.yml</code></strong> releases a project:</p><ol><li>It chooses the next version from existing <code>{project}/v*</code> tags. See <a href="./ci-cd">CI/CD</a>.</li><li>It writes that version into the project&#39;s <code>package.json</code> and <code>CHANGELOG.md</code> and commits those files. Plugin PHP files and theme <code>style.css</code> in git are <strong>not</strong> modified.</li><li>The release zip (<code>&lt;project&gt;-&lt;version&gt;.zip</code>) gets the <code>Version:</code> header set to that version, including alphas: <ul><li><strong>Theme</strong> — <code>Version:</code> line in <code>style.css</code></li><li><strong>Plugin</strong> — <code>* Version:</code> line in <code>&lt;nx-project-name&gt;.php</code>, or the first PHP file in the project root that contains <code>Plugin Name:</code></li></ul></li><li>That header change exists only inside the zip attached to the GitHub Release.</li></ol><p>You do not edit the version by hand before a release. The placeholder in source (for example <code>1.0.0</code>) can stay as-is.</p><h2 id="communicating-version-bumps" tabindex="-1">Communicating version bumps <a class="header-anchor" href="#communicating-version-bumps" aria-label="Permalink to “Communicating version bumps”">​</a></h2><ul><li>Document breaking changes in package <code>docs/</code> or changelog files as agreed by the team.</li></ul>',18)])])}const m=o(i,[["render",s]]);export{p as __pageData,m as default};
